// n8n "Function" node
// Input examples handled:
// - items[0].json (an array of contacts)           ← like your latest payload
// - items[0].json.output (stringified array)
// - items[] already 1-per-item with {name, linkedin*}
//
// Output items: { name, firstname, lastname, linkedinurl }
//
// No hard throws; returns [] if nothing usable.

function normSpace(s = "") {
  return String(s || "").trim().replace(/\s+/g, " ");
}

function isLinkedInProfile(url = "") {
  const u = String(url || "").trim();
  // Accept /in/ profiles primarily; allow locale/edge variants via /in/ first
  return /^https?:\/\/(www\.)?linkedin\.com\/in\/[^\/?#]+/i.test(u);
}

// Titles to drop from start; suffixes from end (case-insensitive)
const PREFIXES = ["mr","mrs","ms","miss","mx","dr","prof","prof.","engr","eng","sir","madam"];
const SUFFIXES = ["jr","sr","ii","iii","iv","v","phd","mba","msc","md","esq","cfa","frsa","acca","aca","cpa"];
// Surname particles to keep with the last name
const SURNAME_PARTICLES = new Set([
  "da","de","del","della","der","di","dos","das","du","la","le",
  "van","von","vande","vander","ter","st","st.","al","bin","ibn","binti","mac","mc","o'","d'"
]);

function stripDecorations(nameRaw = "") {
  let n = normSpace(nameRaw);
  if (!n) return "";
  // remove leading prefixes
  n = n.replace(new RegExp(`^(?:${PREFIXES.join("|")})\\.?\\s+`, "i"), "");
  // remove trailing suffixes (optionally comma-separated)
  n = n.replace(new RegExp(`\\s*,?\\s+(?:${SUFFIXES.join("|")})\\.?$`, "i"), "");
  return normSpace(n);
}

function splitFirstLast(fullNameRaw = "") {
  const fullName = stripDecorations(fullNameRaw);
  if (!fullName) return { firstname: "", lastname: "", name: "" };

  const parts = fullName.split(/\s+/);
  if (parts.length === 1) {
    return { firstname: parts[0], lastname: "", name: parts[0] };
  }
  if (parts.length === 2) {
    return { firstname: parts[0], lastname: parts[1], name: fullName };
  }

  // 3+ tokens: keep surname particles with the last name
  const lower = parts.map(p => p.toLowerCase());
  let startSurname = parts.length - 1;
  while (startSurname - 1 >= 1) {
    if (SURNAME_PARTICLES.has(lower[startSurname - 1])) startSurname--;
    else break;
  }
  return {
    firstname: parts[0],
    lastname: parts.slice(startSurname).join(" "),
    name: fullName
  };
}

function readContactsFromInput(inputItems) {
  if (!Array.isArray(inputItems) || inputItems.length === 0) return [];

  const first = inputItems[0]?.json;

  // Case A: items[0].json is already the array
  if (Array.isArray(first)) return first;

  // Case B: items[0].json.output is a JSON string
  if (first && typeof first.output === "string") {
    try {
      const parsed = JSON.parse(first.output);
      if (Array.isArray(parsed)) return parsed;
    } catch {}
  }

  // Case C: items[0].json.output is already an array
  if (first && Array.isArray(first.output)) return first.output;

  // Case D: upstream fed one item per contact
  if (inputItems.every(it => it?.json && (it.json.name || it.json.linkedin || it.json.linkedin_url))) {
    return inputItems.map(it => it.json);
  }

  return [];
}

function normalizeRecord(rec = {}) {
  const name = normSpace(rec.name);
  // accept either linkedin or linkedin_url; prefer _url if present
  const linkedinurl = normSpace(rec.linkedin_url || rec.linkedin || "");
  return { name, linkedinurl };
}

function dedupeAndTransform(rawList = []) {
  const byKey = new Map(); // key = normalized full name (lowercase)

  for (const r of rawList) {
    const base = normalizeRecord(r);
    if (!base.name || !isLinkedInProfile(base.linkedinurl)) continue;

    const parsed = splitFirstLast(base.name);
    if (!parsed.name) continue;

    const out = {
      name: parsed.name,
      firstname: parsed.firstname,
      lastname: parsed.lastname,
      linkedinurl: base.linkedinurl
    };

    const key = parsed.name.toLowerCase();

    if (!byKey.has(key)) {
      byKey.set(key, out);
      continue;
    }

    // Prefer the longer linkedinurl (often more specific) on ties
    const curr = byKey.get(key);
    if (out.linkedinurl.length > curr.linkedinurl.length) {
      byKey.set(key, out);
    }
  }

  // Sort for stability (lastname, then firstname)
  return Array.from(byKey.values()).sort((a, b) => {
    const ln = a.lastname.localeCompare(b.lastname);
    return ln !== 0 ? ln : a.firstname.localeCompare(b.firstname);
  });
}

// ---- main ----
const contacts = readContactsFromInput(items);
const finalized = dedupeAndTransform(contacts);

// Preserve lineage so expressions after this node work.
// If you had one source item, pair all to item 0.
// If you had N source items 1:1, you can pair each to its own index.
// Here we conservatively pair to 0 (safest for "one blob in, many out").
return finalized.map(row => ({
  json: row,
  pairedItem: { item: 0 }
}));

